#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _Time;
uniform 	vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
uniform 	vec4 hlslcc_mtx4x4unity_MatrixVP[4];
uniform 	mediump float _HG_UV_ROTATION;
uniform 	mediump vec4 _Rotation0;
uniform 	mediump vec4 _Rotation1;
uniform 	mediump vec4 _Rotation2;
uniform 	mediump vec4 _Rotation3;
uniform 	vec4 _MainTex_ST;
uniform 	vec4 _DissolveTex_ST;
uniform 	vec4 _DisturbTex_ST;
uniform 	vec4 _RamTex_ST;
uniform 	mediump float _MainUSpeed;
uniform 	mediump float _MainVSpeed;
uniform 	mediump float _DissolveUSpeed;
uniform 	mediump float _DissolveVSpeed;
uniform 	mediump float _DisturbUSpeed;
uniform 	mediump float _DisturbVSpeed;
in highp vec4 in_POSITION0;

in mediump vec2 in_TEXCOORD0;
uniform mediump vec2 arkMainUVOffset;
in mediump vec4 in_COLOR0;
out mediump vec4 vs_TEXCOORD0;
out mediump vec4 vs_COLOR0;
out mediump vec4 vs_TEXCOORD1;
out mediump vec2 vs_TEXCOORD2;
vec4 u_xlat0;
vec4 u_xlat1;
mediump vec2 u_xlat16_2;
vec2 u_xlat3;
vec2 u_xlat8;
vec2 u_xlat9;
bool u_xlatb9;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    u_xlat8.x = _Time.y * _DissolveUSpeed;
    u_xlat8.y = _Time.y * _DissolveVSpeed;
    u_xlat0.xy = fract(u_xlat8.xy);
    u_xlat8.xy = in_TEXCOORD0.xy * _DissolveTex_ST.xy + _DissolveTex_ST.zw;
    u_xlat16_2.xy = u_xlat8.xy + vec2(-0.5, -0.5);
    u_xlat9.x = dot(u_xlat16_2.xy, _Rotation1.xz);
    u_xlat9.y = dot(u_xlat16_2.xy, _Rotation1.yw);
    u_xlat1.xy = u_xlat9.xy + vec2(0.5, 0.5);
    u_xlatb9 = 0.5<_HG_UV_ROTATION;
    u_xlat16_2.xy = (bool(u_xlatb9)) ? u_xlat1.xy : u_xlat8.xy;
    u_xlat0.zw = u_xlat0.xy + u_xlat16_2.xy;
    u_xlat1.xy = in_TEXCOORD0.xy * _MainTex_ST.xy + _MainTex_ST.zw;
    u_xlat16_2.xy = u_xlat1.xy + vec2(-0.5, -0.5);
    u_xlat3.x = dot(u_xlat16_2.xy, _Rotation0.xz);
    u_xlat3.y = dot(u_xlat16_2.xy, _Rotation0.yw);
    u_xlat3.xy = u_xlat3.xy + vec2(0.5, 0.5);
    u_xlat16_2.xy = (bool(u_xlatb9)) ? u_xlat3.xy : u_xlat1.xy;
    u_xlat1.xy = _Time.yy * vec2(_MainUSpeed, _MainVSpeed);
    u_xlat1.xy = fract(u_xlat1.xy);
    u_xlat0.xy = u_xlat1.xy + u_xlat16_2.xy;
    vs_TEXCOORD0 = u_xlat0;
    vs_COLOR0 = in_COLOR0;
    u_xlat0.xy = in_TEXCOORD0.xy * _DisturbTex_ST.xy + _DisturbTex_ST.zw;
    u_xlat16_2.xy = u_xlat0.xy + vec2(-0.5, -0.5);
    u_xlat8.x = dot(u_xlat16_2.xy, _Rotation3.xz);
    u_xlat8.y = dot(u_xlat16_2.xy, _Rotation3.yw);
    u_xlat8.xy = u_xlat8.xy + vec2(0.5, 0.5);
    u_xlat16_2.xy = (bool(u_xlatb9)) ? u_xlat8.xy : u_xlat0.xy;
    u_xlat8.x = _Time.y * _DisturbUSpeed;
    u_xlat8.y = _Time.y * _DisturbVSpeed;
    u_xlat0.xy = fract(u_xlat8.xy);
    u_xlat0.xy = u_xlat0.xy + u_xlat16_2.xy;
    vs_TEXCOORD1.zw = u_xlat0.xy;
    u_xlat0.xy = in_TEXCOORD0.xy * _RamTex_ST.xy + _RamTex_ST.zw;
    u_xlat16_2.xy = u_xlat0.xy + vec2(-0.5, -0.5);
    u_xlat1.x = dot(u_xlat16_2.xy, _Rotation2.xz);
    u_xlat1.y = dot(u_xlat16_2.xy, _Rotation2.yw);
    u_xlat8.xy = u_xlat1.xy + vec2(0.5, 0.5);
    vs_TEXCOORD1.xy = (bool(u_xlatb9)) ? u_xlat8.xy : u_xlat0.xy;
    vs_TEXCOORD2.xy = vec2(0.0, 0.0);
    return;
}

