#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	mediump float _MainTexChannel;
uniform 	mediump float _DisturbTexChannel;
uniform 	mediump float _DissolvTexChannel;
uniform 	mediump float _RamTexChannel;
uniform 	mediump vec4 _MainColor;
uniform 	mediump float _Opacity;
uniform 	mediump float _DisturbInfluenceDissolveUV;
uniform 	mediump float _DisturbInfluenceMainUV;
uniform 	mediump float _Amount;
uniform 	mediump float _BorderWidth;
uniform 	mediump float _IntensityU;
uniform 	mediump float _IntensityV;
UNITY_LOCATION(0) uniform mediump sampler2D _RamTex;
UNITY_LOCATION(1) uniform mediump sampler2D _DisturbTex;
UNITY_LOCATION(2) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(3) uniform mediump sampler2D _DissolveTex;
in mediump vec4 vs_TEXCOORD0;
in mediump vec4 vs_COLOR0;
in mediump vec4 vs_TEXCOORD1;
in mediump vec2 vs_TEXCOORD2;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
mediump vec4 u_xlat16_0;
vec4 u_xlat1;
bvec4 u_xlatb1;
mediump vec4 u_xlat16_2;
bvec4 u_xlatb2;
vec4 u_xlat3;
mediump vec2 u_xlat16_3;
bvec4 u_xlatb4;
mediump float u_xlat16_5;
mediump vec2 u_xlat16_9;
mediump float u_xlat16_11;
mediump vec2 u_xlat16_15;
mediump float u_xlat16_17;
void main()
{
    u_xlat0 = texture(_RamTex, vs_TEXCOORD1.xy);
    u_xlatb1 = equal(vec4(vec4(_RamTexChannel, _RamTexChannel, _RamTexChannel, _RamTexChannel)), vec4(0.0, 1.0, 2.0, 3.0));
    u_xlat16_2.x = (u_xlatb1.w) ? u_xlat0.z : u_xlat0.w;
    u_xlat16_2.x = (u_xlatb1.z) ? u_xlat0.y : u_xlat16_2.x;
    u_xlat16_2.x = (u_xlatb1.y) ? u_xlat0.x : u_xlat16_2.x;
    u_xlat16_0 = (u_xlatb1.x) ? u_xlat0 : u_xlat16_2.xxxx;
    u_xlat1 = texture(_DisturbTex, vs_TEXCOORD1.zw);
    u_xlatb2 = equal(vec4(_DisturbTexChannel, _DisturbTexChannel, _DisturbTexChannel, _MainTexChannel), vec4(0.0, 1.0, 2.0, 0.0));
    u_xlat16_3.x = (u_xlatb2.z) ? u_xlat1.z : u_xlat1.w;
    u_xlat16_3.x = (u_xlatb2.y) ? u_xlat1.y : u_xlat16_3.x;
    u_xlat16_3.x = (u_xlatb2.x) ? u_xlat1.x : u_xlat16_3.x;
    u_xlat16_9.xy = vs_TEXCOORD2.yy + vec2(_IntensityU, _IntensityV);
    u_xlat16_3.xy = u_xlat16_9.xy * u_xlat16_3.xx;
    u_xlat16_15.xy = u_xlat16_3.xy * vec2(_DisturbInfluenceMainUV) + vs_TEXCOORD0.xy;
    u_xlat16_3.xy = vec2(vec2(_DisturbInfluenceDissolveUV, _DisturbInfluenceDissolveUV)) * u_xlat16_3.xy + vs_TEXCOORD0.zw;
    u_xlat1 = texture(_DissolveTex, u_xlat16_3.xy);
    u_xlat3 = texture(_MainTex, u_xlat16_15.xy);
    u_xlatb4 = equal(vec4(_MainTexChannel, _MainTexChannel, _MainTexChannel, _DissolvTexChannel), vec4(1.0, 2.0, 3.0, 0.0));
    u_xlat16_5 = (u_xlatb4.z) ? u_xlat3.z : u_xlat3.w;
    u_xlat16_5 = (u_xlatb4.y) ? u_xlat3.y : u_xlat16_5;
    u_xlat16_5 = (u_xlatb4.x) ? u_xlat3.x : u_xlat16_5;
    u_xlat16_2 = (u_xlatb2.w) ? u_xlat3 : vec4(u_xlat16_5);
    u_xlat16_2 = u_xlat16_2 * _MainColor;
    u_xlat16_2 = u_xlat16_2 * vs_COLOR0;
    u_xlat16_0 = u_xlat16_0 * u_xlat16_2;
    u_xlat16_5 = dot(u_xlat16_0.ww, vec2(_Opacity));
    SV_Target0.xyz = u_xlat16_0.xyz * vec3(2.0, 2.0, 2.0);
    u_xlatb4.xy = equal(vec4(vec4(_DissolvTexChannel, _DissolvTexChannel, _DissolvTexChannel, _DissolvTexChannel)), vec4(1.0, 2.0, 0.0, 0.0)).xy;
    u_xlat16_11 = (u_xlatb4.y) ? u_xlat1.z : u_xlat1.w;
    u_xlat16_11 = (u_xlatb4.x) ? u_xlat1.y : u_xlat16_11;
    u_xlat16_11 = (u_xlatb4.w) ? u_xlat1.x : u_xlat16_11;
    u_xlat16_17 = vs_TEXCOORD2.x + _Amount;
    u_xlat16_11 = (-u_xlat16_17) + u_xlat16_11;
    u_xlat16_17 = u_xlat16_17 + 0.5;
    u_xlat16_17 = roundEven(u_xlat16_17);
    u_xlat16_17 = (-u_xlat16_17) + 1.0;
    u_xlat16_11 = _BorderWidth * u_xlat16_17 + u_xlat16_11;
    u_xlat16_11 = u_xlat16_11 / _BorderWidth;
    u_xlat16_11 = clamp(u_xlat16_11, 0.0, 1.0);
    SV_Target0.w = u_xlat16_11 * u_xlat16_5;
    SV_Target0.w = clamp(SV_Target0.w, 0.0, 1.0);
    return;
}

